{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Ipratropium, the closest retrieved analogue (Morgan 0.6111) with the same quaternary tropane tropate ester core, had an absolute oral bioavailability of only 3.3% (range 0.9-6.1%) in healthy volunteers after a 20 mg oral dose, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tiotropium, which shares the epoxide-fused quaternary tropane scaffold of the query, showed an absolute oral bioavailability of only 2-3% in healthy humans, demonstrating very poor gastrointestinal absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Ipratropium's low oral bioavailability in humans is partly attributed to active intestinal mucosal secretion, a mechanism expected to apply to the query's quaternary ammonium tropane structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester with an epoxide bridge, closely related to ipratropium and tiotropium. Both close analogues show absolute oral bioavailability of only 2-3% in humans, far below the 20% threshold, and the quaternary ammonium charge is a well-established absorption barrier. Therefore the query is predicted to have low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for oxitropium itself is present in the evidence set; the prediction relies on close structural analogues.",
    "The specific effect of the N-ethyl versus N-isopropyl or N-methyl quaternary substituent on absorption is not directly quantified, though all quaternary tropane analogues show very low oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

